mapper.sql:
WHERE data_package_id = #{q.dataPackageId}
  AND generation = #{q.generation}

  AND phone LIKE CONCAT('%', #{q.phone}, '%')


  AND pool_status = #{q.poolStatusCode}


  AND country_iso2 IS NULL


  AND country_iso2 = #{q.countryIso2}

mapper.select:
SELECT pool_status AS poolStatus, COUNT(*) AS rowCount
FROM data_package_phone
WHERE data_package_id = #{dataPackageId}
  AND generation = #{generation}
GROUP BY pool_status

SELECT phone.tenant_id AS tenantId, phone.id
FROM data_package_phone phone
INNER JOIN data_package package
  ON package.id = phone.data_package_id
 AND package.tenant_id = phone.tenant_id
WHERE (
  package.deleted_at IS NOT NULL
  AND package.deleted_at <= #{deletedBefore}
) OR (
  phone.generation < package.current_generation
  AND EXISTS (
    SELECT 1
    FROM data_package_import switched
    WHERE switched.tenant_id = phone.tenant_id
      AND switched.data_package_id = phone.data_package_id
      AND switched.generation = phone.generation + 1
      AND switched.import_mode = #{overwriteMode}
      AND switched.status = #{successStatus}
      AND switched.finished_at IS NOT NULL
      AND switched.finished_at <= #{retiredBefore}
  )
)
ORDER BY phone.id ASC
LIMIT #{limit}
